(23, '2025-10-14', 'HUZAIFA ALIYAN', '971525538661', '971525538661', 'Huzaifaa737@gmail.com', 'Indeed', 'R1', 'National Stock Exchange', 'Tele Sales Assistant', '', 'came to Dubai to pursuing Masters - last semester - has gotten the NOC for work - has forex experience and real estate - seems to prefer real estate - seems manipulative - average in communication but is super confident - age in 26 - lives in barsha heights', NULL, NULL, NULL, NULL, '2025-10-14 13:31:55', '2025-10-15 07:04:27'),
(24, '2025-10-14', 'ABDUL MANAN', '971586563516', '971586563516', 'abdulmananazhar2104@gmail.com', 'INDEED', 'R1', NULL, NULL, '', 'English, Urdu - has his own visa - lives in Internet City - started sales in 2019 then moved to customer service role - good in communication - is currently working part time for a supermarket - salary expectation is AED 2500 to 3500', NULL, NULL, NULL, NULL, '2025-10-14 13:31:55', '2025-10-14 13:31:55'),
(25, '2025-10-14', 'MOHAMMED SHARHAN FAROOK', '971502339347', '971502339347', 'sharhanmuhd@gmail.com', 'INDEED', 'HR SCREENING', NULL, NULL, '', 'does not seem very strong in terms of communication - could not complete the call as was on duty', NULL, NULL, NULL, NULL, '2025-10-14 13:31:55', '2025-10-14 13:31:55'),
(26, '2025-10-14', 'MOINUDDIN', '971524285034', '971524285034', 'moinnaaz77@gmail.com', 'INDEED', 'HR SCREENING', NULL, NULL, '', 'English, Hindi, Gujrati - is handling 3 stores - operations, cashier, merchandising, etc - current salary AED 3500 - lives in Mankhool - works in Jebel Ali - has 5 years handling Exness Accounts - handle customer accounts - manages customer accounts - average in communication', NULL, NULL, NULL, NULL, '2025-10-14 13:31:55', '2025-10-14 13:31:55'),
(27, '2025-10-14', 'DAVINDER KUMAR', '971556619805', '971556619805', 'Davinderkumar120014@gmail.com', 'WALK-IN', 'R1', NULL, NULL, '', 'HK - Working in Business Bay - is in gaming industry - galaxy exchange - hindi, english - current salary AED 3000 - okayish - not very firm on english but seemed confident', NULL, NULL, NULL, NULL, '2025-10-14 13:31:55', '2025-10-14 13:31:55'),
(28, '2025-10-14', 'ABDULLAH NAVEED', '971528420285', '971528420285', 'adnant797@gmail.com', 'EMPLOYEE REFERENCE', 'HR SCREENING', NULL, NULL, '', 'HK - Employee Reference - Anam - tried calling - no response', NULL, NULL, NULL, NULL, '2025-10-14 13:31:55', '2025-10-14 13:31:55'),
(29, '2025-10-14', 'MOHD GHOUSE PASHA', '971583004345', '971583004345', 'ghousemohd8523@gmail.com', 'EMPLOYEE REFERENCE', 'R1', NULL, NULL, '', 'HK - Sumeet Reference - English, Hindi, Telugu - 5 years of experience - Airtel Black Process - handled L2 calls - when agents not able to handle their calls it was transferred to him - more like customer satisfaction team - came to Dubai on 1st Oct - looking for sales or customer service - Abu Hail', NULL, NULL, NULL, NULL, '2025-10-14 13:31:55', '2025-10-14 13:31:55'),
